  'settings.help.collector.title': 'Collector ก่อนที่จะมีอะไรถูกดาวน์โหลด',
  'settings.help.collector.body':
    'ลิงก์ใหม่จะไปที่ Collector ก่อน ไม่ใช่คิว: พื้นที่ชั่วคราวสำหรับตรวจสอบชื่อ ขนาด และคำเตือนรายการซ้ำก่อนที่อะไรจะเริ่มต้น การยืนยันอัตโนมัติสามารถข้ามขั้นตอนนี้ได้ พร้อมการหน่วงเวลาที่เลือกได้ เมื่อยืนยันแล้ว ลิงก์จะเริ่มทันทีหรือรอในคิว ขึ้นอยู่กับการเริ่มอัตโนมัติ',
  'settings.help.collector.link': 'เปิดการตั้งค่าทั่วไป',

  'settings.help.rules.title': 'กฎ: แพ็กเกจ โฟลเดอร์ และสิ่งที่จะถูกเก็บไว้',
  'settings.help.rules.body':
    'Packagizer เปลี่ยนชื่อลิงก์ เลือกโฟลเดอร์ของมัน และตั้งค่าตัวเลือกการดาวน์โหลดเมื่อมาถึง โดยอิงจากเงื่อนไขที่คุณเขียน ตัวกรองลิงก์จะตัดสินว่าลิงก์จะถูกเก็บไว้หรือไม่ - และต่างจากตัวกรองที่แค่ทำให้ลิงก์หายไปเฉย ๆ การปฏิเสธจะระบุกฎที่ทำให้เกิดเรื่องนั้นเสมอ พร้อมเหตุผล',
  'settings.help.rules.link': 'เปิดกฎ',

  'settings.help.queue.title': 'การจัดการคิว',
  'settings.help.queue.body':
    'หยุดชั่วคราว ทำต่อ หรือจัดเรียงลิงก์ใหม่ ไม่ว่าจะทีละลิงก์หรือทั้งแพ็กเกจ การหยุดคิวเป็นสองการกระทำที่ต่างกัน: การหยุดจะปล่อยสิ่งที่กำลังทำงานอยู่ไว้ไม่แตะต้องเพื่อให้เสร็จเอง ในขณะที่การหยุดการถ่ายโอนทั้งหมดทันทีจะแสดงก่อนว่าอะไรจะสูญเสียไป และจะดำเนินต่อก็ต่อเมื่อคุณยืนยันแล้วเท่านั้น - นั่นคือเหตุผลที่คำเตือนนั้นมีไว้สำหรับการถ่ายโอนที่ไม่สามารถทำต่อจากจุดที่หยุดไว้ได้',
  'settings.help.queue.b1': 'ลิงก์เดียวสามารถแทนที่จำนวนการเชื่อมต่อรวมหรือสวิตช์แตกไฟล์หลังดาวน์โหลดได้',
  'settings.help.queue.b2': 'ลิงก์ที่ซ้ำกับลิงก์ที่มีอยู่แล้วในรายการจะถูกปฏิเสธเสมอ ก่อนที่จะไปถึง Collector ด้วยซ้ำ',

  'settings.help.limits.title': 'การหลีกเลี่ยงขีดจำกัดของโฮสเตอร์',
  'settings.help.limits.body': 'สามวิธีที่เป็นอิสระจากกันเพื่อไม่ให้ขีดจำกัดฟรีกลายเป็นเพดาน:',
  'settings.help.limits.b1':
    'การเชื่อมต่อ - กระจายการดาวน์โหลดไปมากกว่าหนึ่งเส้นทางขาออก (สายที่สอง พร็อกซี SOCKS) แทนที่จะออกผ่านที่อยู่ของเครื่องนี้เองเสมอ',
  'settings.help.limits.b2':
    'การเชื่อมต่อใหม่ - ขอที่อยู่สาธารณะใหม่จากเราเตอร์ ซึ่งเป็นสิ่งเดียวที่ยกเลิกขีดจำกัดที่ผูกกับที่อยู่นั้นเองได้จริง (UPnP โปรแกรมภายนอก สคริปต์ หรือการเล่นคำขอ HTTP ซ้ำกับหน้าจัดการของเราเตอร์ - สคริปต์ JDownloader LiveHeader/curl ที่มีอยู่แล้วทำงานได้เหมือนเดิม)',
  'settings.help.limits.b3':
    'บัญชี - บันทึกข้อมูลเข้าสู่ระบบพรีเมียมหรือ debrid (Real-Debrid, AllDebrid, TorBox และอื่น ๆ) เพื่อให้ลิงก์ที่มีสิทธิ์ถูกดึงมาด้วยความเร็วเต็มที่แทนขีดจำกัดฟรี',
