  'settings.help.limits.link3': 'เปิดบัญชี',

  'settings.help.captcha.title': 'Captcha',
  'settings.help.captcha.body':
    'เมื่อโฮสเตอร์ขอ captcha ตัวแก้อัตโนมัติที่คุณตั้งค่าไว้จะถูกลองก่อน ตามลำดับที่คุณกำหนด สิ่งที่มันแก้ไม่ได้ - หรือถ้าไม่มีการตั้งค่าตัวแก้ไว้เลย - จะถูกนำมาให้คุณแทนที่จะล้มเหลวอย่างเงียบ ๆ',
