  'settings.help.instances.title': 'การรันมากกว่าหนึ่งอินสแตนซ์',
  'settings.help.instances.body': 'เพิ่ม KnightLoader อีกตัวเป็นคู่ แล้วคิวของมันจะปรากฏบนแดชบอร์ดนี้ด้วย ในเครือข่ายเดียวกันนี่คือการเรียก API ของอีกอินสแตนซ์โดยตรง แบบเดียวกับที่เบราว์เซอร์ทำ ข้ามเครือข่าย สิบสองคำจะจับคู่ทั้งสองผ่านรีเลย์ที่คุณโฮสต์เองได้',
