  'settings.help.access.body':
    'รหัสผ่านจะล็อกอินเทอร์เฟซทั้งหมดไว้หลังคุกกี้เซสชัน หน้าการเข้าถึงยังแสดงรายการพอร์ตรับข้อมูลและวิธีการเข้าถึงของบิลด์นี้ พร้อมเหตุผล - เพื่อให้พอร์ตที่เปิดอยู่ซึ่งไม่รู้จักมีคำตอบแทนที่จะเป็นการเดา หน้าการวินิจฉัยจะสร้างไฟล์สำหรับแนบไปกับรายงานข้อบกพร่อง: เวอร์ชันและข้อมูลบิลด์ การตั้งค่าปัจจุบันโดยลบรหัสผ่านทั้งหมดออก บรรทัดล็อกล่าสุดของโพรเซสนี้ และมี goroutine ทำงานอยู่กี่ตัว',
  'settings.help.access.link1': 'เปิดการตั้งค่าการเข้าถึง',
  'settings.help.access.link2': 'เปิดการวินิจฉัย',

