  'onboarding.welcome.body': 'KnightLoader คือโปรแกรมจัดการดาวน์โหลดแบบโฮสต์เอง: วางหรือลากลิงก์มาวาง แล้วมันจะถูกดึงโดยแบ็กเอนด์ที่จัดการมันได้จริง - เอนจินในตัวสำหรับลิงก์ไฟล์ทั่วไป yt-dlp สำหรับหน้าสื่อ บริการ debrid สำหรับโฮสต์ที่คุณจ่ายเงินอยู่แล้ว หรือ JDownloader แบบไม่มีหน้าจอสำหรับส่วนที่เหลือทั้งหมด ทัวร์สั้น ๆ นี้ครอบคลุมการตั้งค่าเดียวที่คุ้มค่าจะตรวจสอบก่อนเริ่มต้น',
  'onboarding.welcome.langLabel': 'ภาษาของอินเทอร์เฟซ',
  'onboarding.folder.title': 'ไฟล์ควรไปอยู่ที่ไหน?',
  'onboarding.folder.body': 'นี่คือโฟลเดอร์ที่ดาวน์โหลดที่เสร็จแล้วจะถูกเขียนลงไป พิมพ์เส้นทางหรือเรียกดูเซิร์ฟเวอร์เพื่อเลือกโฟลเดอร์ - คุณสามารถเปลี่ยนได้อีกครั้งเมื่อไรก็ได้จากหน้าการตั้งค่าทั่วไป',
  'onboarding.accounts.title': 'โฮสต์พรีเมียม เมื่อใดก็ตามที่คุณต้องการ',
  'onboarding.accounts.body': 'คิวทำงานได้โดยไม่ต้องมีบัญชีเลย เมื่อคุณต้องการความเร็วเต็มที่จากโฮสต์หรือบริการ debrid ที่คุณจ่ายเงินอยู่แล้ว ให้เพิ่มข้อมูลเข้าสู่ระบบไว้ที่บัญชี - ตอนนี้ยังไม่ต้องตั้งค่าอะไรที่นี่',
  'onboarding.accounts.link': 'เปิดบัญชี',
  'onboarding.finished.title': 'คุณพร้อมแล้ว',
  'onboarding.finished.body': 'ทัวร์จบลงเท่านี้ หน้าวิธีใช้ในการตั้งค่ามีคำอธิบายแบบเต็มเกี่ยวกับทุกอย่างที่รุ่นนี้ทำได้ และตัวควบคุมส่วนใหญ่มีคำอธิบายของตัวเองอยู่หลังไอคอน (i)',

