  'settings.nav.shortcuts': 'ปุ่มลัด',
  'settings.shortcuts.subtitle': 'คำสั่งทั้งหมดที่มีปุ่มลัดคีย์บอร์ดเริ่มต้น จัดกลุ่มตามจุดที่ใช้งาน เปลี่ยนการผูกปุ่ม หรือรีเซ็ตกลับเป็นค่าเริ่มต้น',
